import{_ as r,y as a,a as s,o as n,a2 as o,D as i}from"./chunks/framework.DCcmcJcL.js";const f=JSON.parse('{"title":"Google Captcha","description":"","frontmatter":{},"headers":[],"relativePath":"configure/google-captcha.md","filePath":"configure/google-captcha.md","lastUpdated":1789441803000}'),l={name:"configure/google-captcha.md"};function c(h,e,g,d,p,u){const t=a("ImagePopup");return n(),s("div",null,[e[0]||(e[0]=o('<h1 id="google-captcha" tabindex="-1">Google Captcha <a class="header-anchor" href="#google-captcha" aria-label="Permalink to &quot;Google Captcha&quot;">​</a></h1><p>Google reCAPTCHA protects your storefront&#39;s forms from bots. It gives every request a score, and rejects requests whose score is below the threshold you set. Bagisto uses <strong>reCAPTCHA Enterprise</strong>, which needs a Google Cloud project, an API key and a site key.</p><h2 id="get-the-keys-from-google-cloud" tabindex="-1">Get the keys from Google Cloud <a class="header-anchor" href="#get-the-keys-from-google-cloud" aria-label="Permalink to &quot;Get the keys from Google Cloud&quot;">​</a></h2><h3 id="project-id" tabindex="-1">Project ID <a class="header-anchor" href="#project-id" aria-label="Permalink to &quot;Project ID&quot;">​</a></h3><ol><li>Open the <a href="https://console.cloud.google.com/" target="_blank" rel="noreferrer">Google Cloud console</a>.</li><li>Create a project, or choose an existing one.</li><li>Copy the project ID from the project dashboard. It is not the same as the project name.</li></ol><h3 id="api-key" tabindex="-1">API key <a class="header-anchor" href="#api-key" aria-label="Permalink to &quot;API key&quot;">​</a></h3><ol><li>In the Google Cloud console, open the <strong>Credentials</strong> page of the <strong>APIs &amp; Services</strong> menu.</li><li>Create an API key.</li><li>Copy the new key.</li></ol><h3 id="site-key" tabindex="-1">Site key <a class="header-anchor" href="#site-key" aria-label="Permalink to &quot;Site key&quot;">​</a></h3><ol><li>In the Google Cloud console, search for the <strong>reCAPTCHA</strong> service.</li><li>Create a key for a website, using score-based (reCAPTCHA v3) verification.</li><li>Add your store&#39;s domain, such as <code>example.com</code>.</li><li>Copy the site key.</li></ol><h2 id="credentials" tabindex="-1">Credentials <a class="header-anchor" href="#credentials" aria-label="Permalink to &quot;Credentials&quot;">​</a></h2><p>All settings are saved per channel, so choose the channel at the top of the screen first when your store has more than one.</p><ol><li>Go to <strong>Configure &gt;&gt; Customer &gt;&gt; Google Captcha</strong>.</li><li>In <strong>Credentials</strong>, switch <strong>Status</strong> on. <strong>Project ID</strong>, <strong>API Key</strong>, <strong>Site Key</strong> and <strong>Score Threshold</strong> appear.</li><li>Enter the <strong>Project ID</strong>.</li><li>Enter the <strong>API Key</strong>.</li><li>Enter the <strong>Site Key</strong>.</li><li>Enter the <strong>Score Threshold</strong>, a number from <code>0.0</code> to <code>1.0</code> with one decimal place. The default is <code>0.5</code>.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',12)),i(t,{src:"/images/configure/google-captcha-settings.png",alt:"Credentials section of the Google Captcha screen with Status turned on and placeholder keys"}),e[1]||(e[1]=o('<p>The <strong>Project ID</strong>, <strong>API Key</strong> and <strong>Site Key</strong> are required while <strong>Status</strong> is on. reCAPTCHA scores each request from 0.0, most likely a bot, to 1.0, most likely a person. A request is accepted when its score reaches the threshold, so a higher threshold rejects more requests.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>While <strong>Status</strong> is on, the protected forms reject every request if a key is missing or wrong, or Google can&#39;t be reached. After saving, sign in to the storefront once to check that the captcha accepts you.</p></div><h2 id="where-the-captcha-is-used" tabindex="-1">Where the captcha is used <a class="header-anchor" href="#where-the-captcha-is-used" aria-label="Permalink to &quot;Where the captcha is used&quot;">​</a></h2><p>Once it is on, reCAPTCHA checks these storefront forms:</p><ul><li>Customer sign in and sign up</li><li>Forgot password</li><li>The <strong>Contact Us</strong> page</li><li>The contact form on product pages, which replaces the cart buttons while the cart page is turned off under <a href="./checkout.html">Checkout</a></li><li>Sign in during checkout</li></ul><p>The sign-up and sign-in forms are described in <a href="./../customer/customer-account.html">Customer Account</a>.</p>',6))])}const C=r(l,[["render",c]]);export{f as __pageData,C as default};
